inline const char *LMOIdentifier() {
  return "$LMO";
}

inline bool LMOBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, LMOIdentifier());
}

inline bool SizePrefixedLMOBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, LMOIdentifier(), true);
}

template <bool B = false>
inline bool VerifyLMOBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<LMO>(LMOIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedLMOBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<LMO>(LMOIdentifier());
}

inline void FinishLMOBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<LMO> root) {
  fbb.Finish(root, LMOIdentifier());
}

inline void FinishSizePrefixedLMOBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<LMO> root) {
  fbb.FinishSizePrefixed(root, LMOIdentifier());
}

inline std::unique_ptr<LMOT> UnPackLMO(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<LMOT>(GetLMO(buf)->UnPack(res));
}

inline std::unique_ptr<LMOT> UnPackSizePrefixedLMO(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<LMOT>(GetSizePrefixedLMO(buf)->UnPack(res));
}

